import pytest

def count_ways_to_pay(n, a, b, m):
    p = 1000000007
    d = [1] * 300001
    td = [0] * 300001
    L = b[0]

    for i in range(1, n):
        if a[i - 1] != 1:
            t = m % a[i - 1]
            if L < t:
                return 0
            m //= a[i - 1]
            for j in range((L - t) // a[i - 1] + 1):
                d[j] = d[t]
                t += a[i - 1]
            L = j

        k = 0
        for j in range(L + b[i] + 1):
            if j <= L:
                k += d[j]
            k %= p
            td[j] = k
            if j >= b[i]:
                k -= d[j - b[i]]

        L += b[i]
        for j in range(L + 1):
            d[j] = td[j]

    return d[m] if m <= L else 0

@pytest.mark.parametrize("n, a, b, m, expected", [
    (5, [2, 3, 4], [1, 2, 3], 6, 8),
    (3, [2, 3, 4], [1, 2, 3], 9, 0),
    (4, [2, 3, 4], [1, 2, 3], 10, 8),
    (1, [2, 3, 4], [1, 2, 3], 1, 1),
    (2, [2, 3, 4], [1, 2, 3], 2, 0)
])
def test_count_ways_to_pay(n, a, b, m, expected):
    assert count_ways_to_pay(n, a, b, m) == expected
