import pytest

def calculate_tip(amount, rating):
    tips = {
        'terrible': 0,
        'poor': 0.05,
        'good': 0.1,
        'great': 0.15,
        'excellent': 0.2
    }

    rating = rating.lower()

    if rating in tips:
        return ceil(amount * tips[rating])
    else:
        return 'Rating not recognised'

@pytest.mark.parametrize("amount, rating, expected", [
    (100, "terrible", 0),
    (100, "poor", 5),
    (100, "good", 10),
    (100, "great", 15),
    (100, "excellent", 20),
    (100, "amazing", 'Rating not recognised'),
    (100, "bad", 'Rating not recognised')
])
def test_calculate_tip(amount, rating, expected):
    assert calculate_tip(amount, rating) == expected
