import pytest

def count_possible_max_indices(T, test_cases):
    results = []

    for case in test_cases:
        N, S = case
        arr1 = [int(x) for x in list(S)]
        count = 0

        if N == 2:
            results.append(1)
            continue

        if arr1[0] == 1:
            count += 1
        if arr1[-1] == 0:
            count += 1

        for y in range(N - 2):
            if arr1[y] == 0 and arr1[y + 1] == 1:
                count += 1

        results.append(count)

    return results

@pytest.mark.parametrize("T", [
    (1, [(2, "10"), (3, "110")]),
    (2, [(4, "1010"), (5, "11010")])
])
def test_count_possible_max_indices(T):
    assert count_possible_max_indices(*T) == T[1]
